-- Phase 4B controlled AR/AP settlement records.  Client roles retain read-only access.
create type public.settlement_status as enum ('draft','posted','reversed');
create table public.sales_credit_notes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),branch_id uuid references public.branches(id),customer_id uuid not null references public.customers(id),invoice_id uuid references public.sales_invoices(id),credit_note_number text,credit_note_date date not null,reference text,notes text,status public.settlement_status not null default 'draft',subtotal numeric(20,6) not null default 0,tax_total numeric(20,6) not null default 0,grand_total numeric(20,6) not null default 0,posted_journal_id uuid references public.journal_entries(id),posted_at timestamptz,posted_by uuid references auth.users(id),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,credit_note_number));
create table public.sales_credit_note_lines(id uuid primary key default gen_random_uuid(),credit_note_id uuid not null references public.sales_credit_notes(id) on delete cascade,organization_id uuid not null references public.organizations(id),description text not null,quantity numeric(20,6) not null check(quantity>0),unit_price numeric(20,6) not null check(unit_price>=0),discount numeric(20,6) not null default 0 check(discount>=0),tax_rate_id uuid references public.tax_rates(id),revenue_account_id uuid references public.accounts(id));
create table public.purchase_debit_notes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),branch_id uuid references public.branches(id),supplier_id uuid not null references public.suppliers(id),bill_id uuid references public.purchase_bills(id),debit_note_number text,debit_note_date date not null,reference text,notes text,status public.settlement_status not null default 'draft',subtotal numeric(20,6) not null default 0,tax_total numeric(20,6) not null default 0,grand_total numeric(20,6) not null default 0,posted_journal_id uuid references public.journal_entries(id),posted_at timestamptz,posted_by uuid references auth.users(id),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,debit_note_number));
create table public.purchase_debit_note_lines(id uuid primary key default gen_random_uuid(),debit_note_id uuid not null references public.purchase_debit_notes(id) on delete cascade,organization_id uuid not null references public.organizations(id),description text not null,quantity numeric(20,6) not null check(quantity>0),unit_price numeric(20,6) not null check(unit_price>=0),discount numeric(20,6) not null default 0 check(discount>=0),tax_rate_id uuid references public.tax_rates(id),expense_account_id uuid not null references public.accounts(id));
create table public.customer_receipts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),branch_id uuid references public.branches(id),customer_id uuid not null references public.customers(id),receipt_number text,receipt_date date not null,cash_account_id uuid not null references public.accounts(id),amount numeric(20,6) not null check(amount>0),reference text,notes text,status public.settlement_status not null default 'draft',posted_journal_id uuid references public.journal_entries(id),posted_at timestamptz,posted_by uuid references auth.users(id),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,receipt_number));
create table public.supplier_payments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),branch_id uuid references public.branches(id),supplier_id uuid not null references public.suppliers(id),payment_number text,payment_date date not null,cash_account_id uuid not null references public.accounts(id),amount numeric(20,6) not null check(amount>0),reference text,notes text,status public.settlement_status not null default 'draft',posted_journal_id uuid references public.journal_entries(id),posted_at timestamptz,posted_by uuid references auth.users(id),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,payment_number));
create table public.open_item_allocations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),open_item_id uuid not null references public.open_items(id),customer_receipt_id uuid references public.customer_receipts(id),supplier_payment_id uuid references public.supplier_payments(id),sales_credit_note_id uuid references public.sales_credit_notes(id),purchase_debit_note_id uuid references public.purchase_debit_notes(id),amount numeric(20,6) not null check(amount>0),created_at timestamptz not null default now(),check(num_nonnulls(customer_receipt_id,supplier_payment_id,sales_credit_note_id,purchase_debit_note_id)=1),unique(open_item_id,customer_receipt_id),unique(open_item_id,supplier_payment_id),unique(open_item_id,sales_credit_note_id),unique(open_item_id,purchase_debit_note_id));
do $$ declare t text; begin foreach t in array array['sales_credit_notes','sales_credit_note_lines','purchase_debit_notes','purchase_debit_note_lines','customer_receipts','supplier_payments','open_item_allocations'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy sales_credit_notes_member_select on public.sales_credit_notes for select to authenticated using(public.is_active_org_member(organization_id));
create policy purchase_debit_notes_member_select on public.purchase_debit_notes for select to authenticated using(public.is_active_org_member(organization_id));
create policy customer_receipts_member_select on public.customer_receipts for select to authenticated using(public.is_active_org_member(organization_id));
create policy supplier_payments_member_select on public.supplier_payments for select to authenticated using(public.is_active_org_member(organization_id));
create policy allocations_member_select on public.open_item_allocations for select to authenticated using(public.is_active_org_member(organization_id));
revoke all on public.sales_credit_notes,public.sales_credit_note_lines,public.purchase_debit_notes,public.purchase_debit_note_lines,public.customer_receipts,public.supplier_payments,public.open_item_allocations from anon;
grant select on public.sales_credit_notes,public.sales_credit_note_lines,public.purchase_debit_notes,public.purchase_debit_note_lines,public.customer_receipts,public.supplier_payments,public.open_item_allocations to authenticated;

create or replace function public.create_customer_receipt_draft(p_organization_id uuid,p_customer_id uuid,p_receipt_date date,p_cash_account_id uuid,p_amount numeric,p_allocations jsonb default '[]'::jsonb,p_branch_id uuid default null,p_reference text default null,p_notes text default null) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare v_id uuid:=gen_random_uuid(); begin perform public.assert_accounting_owner(p_organization_id); if p_amount<=0 or jsonb_typeof(p_allocations)<>'array' or not exists(select 1 from public.customers where id=p_customer_id and organization_id=p_organization_id and is_active) or not exists(select 1 from public.accounts where id=p_cash_account_id and organization_id=p_organization_id and is_active and account_type in ('cash','bank')) or (p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and organization_id=p_organization_id)) then raise exception 'invalid_receipt'; end if; insert into public.customer_receipts(id,organization_id,branch_id,customer_id,receipt_date,cash_account_id,amount,reference,notes,created_by) values(v_id,p_organization_id,p_branch_id,p_customer_id,p_receipt_date,p_cash_account_id,p_amount,nullif(trim(p_reference),''),nullif(trim(p_notes),''),auth.uid()); perform public.accounting_audit(p_organization_id,'customer_receipt.created','customer_receipt',v_id); return v_id; end; $$;
create or replace function public.update_customer_receipt_draft(p_organization_id uuid,p_receipt_id uuid,p_customer_id uuid,p_receipt_date date,p_cash_account_id uuid,p_amount numeric,p_branch_id uuid default null,p_reference text default null,p_notes text default null) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_accounting_owner(p_organization_id); if p_amount<=0 or not exists(select 1 from public.customers where id=p_customer_id and organization_id=p_organization_id and is_active) or not exists(select 1 from public.accounts where id=p_cash_account_id and organization_id=p_organization_id and is_active and account_type in ('cash','bank')) then raise exception 'invalid_receipt'; end if; update public.customer_receipts set customer_id=p_customer_id,receipt_date=p_receipt_date,cash_account_id=p_cash_account_id,amount=p_amount,branch_id=p_branch_id,reference=nullif(trim(p_reference),''),notes=nullif(trim(p_notes),'') where id=p_receipt_id and organization_id=p_organization_id and status='draft'; if not found then raise exception 'receipt_not_editable'; end if; perform public.accounting_audit(p_organization_id,'customer_receipt.updated','customer_receipt',p_receipt_id); end; $$;
create or replace function public.delete_customer_receipt_draft(p_organization_id uuid,p_receipt_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_accounting_owner(p_organization_id); delete from public.customer_receipts where id=p_receipt_id and organization_id=p_organization_id and status='draft'; if not found then raise exception 'receipt_not_editable'; end if; end; $$;
create or replace function public.post_customer_receipt(p_organization_id uuid,p_receipt_id uuid,p_allocations jsonb default '[]'::jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$ declare d public.customer_receipts%rowtype; x jsonb; i public.open_items%rowtype; v_total numeric:=0; v_amount numeric; v_journal uuid:=gen_random_uuid(); v_ar uuid; v_n bigint; v_prefix text; v_padding smallint; v_suffix text; begin perform public.assert_accounting_owner(p_organization_id); select * into d from public.customer_receipts where id=p_receipt_id and organization_id=p_organization_id for update; if not found then raise exception 'not_found'; end if; if d.status='posted' then return jsonb_build_object('receipt_id',d.id,'journal_id',d.posted_journal_id,'already_posted',true); end if; if jsonb_typeof(p_allocations)<>'array' then raise exception 'invalid_allocations'; end if; for x in select value from jsonb_array_elements(p_allocations) loop v_amount:=(x->>'amount')::numeric; select * into i from public.open_items where id=(x->>'open_item_id')::uuid and organization_id=p_organization_id for update; if not found or i.kind<>'receivable' or i.customer_id<>d.customer_id or v_amount<=0 or v_amount>i.remaining_amount then raise exception 'invalid_receipt_allocation'; end if; v_total:=v_total+v_amount; end loop; if v_total<>d.amount then raise exception 'receipt_allocation_must_equal_amount'; end if; select id into v_ar from public.accounts where organization_id=p_organization_id and system_key='accounts_receivable' and is_active; if v_ar is null then raise exception 'system_account_missing'; end if; insert into public.journal_entries(id,organization_id,branch_id,journal_date,source_type,source_id,description,created_by) values(v_journal,p_organization_id,d.branch_id,d.receipt_date,'customer_receipt',d.id,'Customer receipt',auth.uid()); insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount) values(p_organization_id,v_journal,1,d.cash_account_id,'Customer receipt',d.amount,0),(p_organization_id,v_journal,2,v_ar,'Accounts receivable',0,d.amount); select prefix,padding,suffix,next_number into v_prefix,v_padding,v_suffix,v_n from public.document_sequences where organization_id=p_organization_id and document_type='receipt' and branch_id is null and financial_year_id is null for update; if v_n is null then raise exception 'receipt_sequence_missing'; end if; update public.document_sequences set next_number=next_number+1 where organization_id=p_organization_id and document_type='receipt' and branch_id is null and financial_year_id is null; update public.journal_entries set reference=v_prefix||lpad(v_n::text,v_padding,'0')||coalesce(v_suffix,'') where id=v_journal; perform public.post_journal_entry(p_organization_id,v_journal); for x in select value from jsonb_array_elements(p_allocations) loop v_amount:=(x->>'amount')::numeric; update public.open_items set remaining_amount=remaining_amount-v_amount,status=case when remaining_amount-v_amount=0 then 'settled' else 'partial' end where id=(x->>'open_item_id')::uuid; insert into public.open_item_allocations(organization_id,open_item_id,customer_receipt_id,amount) values(p_organization_id,(x->>'open_item_id')::uuid,d.id,v_amount); end loop; update public.customer_receipts set receipt_number=v_prefix||lpad(v_n::text,v_padding,'0')||coalesce(v_suffix,''),status='posted',posted_journal_id=v_journal,posted_at=now(),posted_by=auth.uid() where id=d.id; perform public.accounting_audit(p_organization_id,'customer_receipt.posted','customer_receipt',d.id); return jsonb_build_object('receipt_id',d.id,'journal_id',v_journal,'already_posted',false); end; $$;
revoke all on function public.create_customer_receipt_draft(uuid,uuid,date,uuid,numeric,jsonb,uuid,text,text),public.update_customer_receipt_draft(uuid,uuid,uuid,date,uuid,numeric,uuid,text,text),public.delete_customer_receipt_draft(uuid,uuid),public.post_customer_receipt(uuid,uuid,jsonb) from public,anon;
grant execute on function public.create_customer_receipt_draft(uuid,uuid,date,uuid,numeric,jsonb,uuid,text,text),public.update_customer_receipt_draft(uuid,uuid,uuid,date,uuid,numeric,uuid,text,text),public.delete_customer_receipt_draft(uuid,uuid),public.post_customer_receipt(uuid,uuid,jsonb) to authenticated;

-- 4B.1 Sales credit notes. Source-line provenance makes the original revenue
-- account and VAT treatment authoritative; clients supply only line ids/quantities.
alter table public.sales_credit_note_lines add column source_invoice_line_id uuid references public.sales_invoice_lines(id);

create or replace function public.replace_sales_credit_note_lines(p_organization_id uuid,p_credit_note_id uuid,p_lines jsonb) returns void language plpgsql security definer set search_path=pg_catalog,public as $$
declare x jsonb; s public.sales_invoice_lines%rowtype; v_invoice uuid;
begin
  perform public.assert_accounting_owner(p_organization_id);
  if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'credit_note_lines_required'; end if;
  select invoice_id into v_invoice from public.sales_credit_notes where id=p_credit_note_id and organization_id=p_organization_id and status='draft' for update;
  if v_invoice is null then raise exception 'credit_note_not_editable'; end if;
  delete from public.sales_credit_note_lines where credit_note_id=p_credit_note_id;
  for x in select value from jsonb_array_elements(p_lines) loop
    select * into s from public.sales_invoice_lines where id=(x->>'source_invoice_line_id')::uuid and invoice_id=v_invoice and organization_id=p_organization_id;
    if not found or coalesce((x->>'quantity')::numeric,0)<=0 or (x->>'quantity')::numeric>s.quantity then raise exception 'invalid_credit_note_line'; end if;
    insert into public.sales_credit_note_lines(credit_note_id,organization_id,source_invoice_line_id,description,quantity,unit_price,discount,tax_rate_id,revenue_account_id)
    values(p_credit_note_id,p_organization_id,s.id,s.description,(x->>'quantity')::numeric,s.unit_price,round(s.discount*(x->>'quantity')::numeric/s.quantity,6),s.tax_rate_id,s.revenue_account_id);
  end loop;
end; $$;

create or replace function public.create_sales_credit_note_draft(p_organization_id uuid,p_customer_id uuid,p_invoice_id uuid,p_credit_note_date date,p_lines jsonb,p_branch_id uuid default null,p_reference text default null,p_notes text default null) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$
declare v_id uuid:=gen_random_uuid();
begin
  perform public.assert_accounting_owner(p_organization_id);
  if not exists(select 1 from public.sales_invoices i join public.customers c on c.id=i.customer_id and c.organization_id=p_organization_id and c.is_active where i.id=p_invoice_id and i.organization_id=p_organization_id and i.status='posted' and i.customer_id=p_customer_id and i.branch_id is not distinct from p_branch_id)
     or (p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and organization_id=p_organization_id)) then raise exception 'invalid_credit_note_source'; end if;
  insert into public.sales_credit_notes(id,organization_id,branch_id,customer_id,invoice_id,credit_note_date,reference,notes,created_by) values(v_id,p_organization_id,p_branch_id,p_customer_id,p_invoice_id,p_credit_note_date,nullif(trim(p_reference),''),nullif(trim(p_notes),''),auth.uid());
  perform public.replace_sales_credit_note_lines(p_organization_id,v_id,p_lines);
  perform public.accounting_audit(p_organization_id,'sales_credit_note.created','sales_credit_note',v_id);
  return v_id;
end; $$;

create or replace function public.update_sales_credit_note_draft(p_organization_id uuid,p_credit_note_id uuid,p_credit_note_date date,p_lines jsonb,p_reference text default null,p_notes text default null) returns void language plpgsql security definer set search_path=pg_catalog,public as $$
begin
  perform public.assert_accounting_owner(p_organization_id);
  update public.sales_credit_notes set credit_note_date=p_credit_note_date,reference=nullif(trim(p_reference),''),notes=nullif(trim(p_notes),'') where id=p_credit_note_id and organization_id=p_organization_id and status='draft';
  if not found then raise exception 'credit_note_not_editable'; end if;
  perform public.replace_sales_credit_note_lines(p_organization_id,p_credit_note_id,p_lines);
  perform public.accounting_audit(p_organization_id,'sales_credit_note.updated','sales_credit_note',p_credit_note_id);
end; $$;

create or replace function public.delete_sales_credit_note_draft(p_organization_id uuid,p_credit_note_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$
begin
  perform public.assert_accounting_owner(p_organization_id);
  delete from public.sales_credit_notes where id=p_credit_note_id and organization_id=p_organization_id and status='draft';
  if not found then raise exception 'credit_note_not_editable'; end if;
end; $$;

create or replace function public.post_sales_credit_note(p_organization_id uuid,p_credit_note_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare d public.sales_credit_notes%rowtype; oi public.open_items%rowtype; l record; v_journal uuid:=gen_random_uuid(); v_ar uuid; v_vat uuid; v_revenue uuid; v_net numeric(20,6):=0; v_tax numeric(20,6):=0; v_amount numeric(20,6); v_tax_amount numeric(20,6); v_line smallint:=0; v_number bigint; v_prefix text; v_padding smallint; v_suffix text;
begin
  perform public.assert_accounting_owner(p_organization_id);
  select * into d from public.sales_credit_notes where id=p_credit_note_id and organization_id=p_organization_id for update;
  if not found then raise exception 'not_found'; end if;
  if d.status='posted' then return jsonb_build_object('credit_note_id',d.id,'journal_id',d.posted_journal_id,'already_posted',true); end if;
  if d.status<>'draft' or not exists(select 1 from public.sales_invoices i where i.id=d.invoice_id and i.organization_id=p_organization_id and i.status='posted' and i.customer_id=d.customer_id and i.branch_id is not distinct from d.branch_id) then raise exception 'credit_note_not_postable'; end if;
  select * into oi from public.open_items where organization_id=p_organization_id and kind='receivable' and customer_id=d.customer_id and source_document_id=d.invoice_id for update;
  if not found then raise exception 'invoice_open_item_missing'; end if;
  for l in select cl.*,sl.quantity source_quantity from public.sales_credit_note_lines cl join public.sales_invoice_lines sl on sl.id=cl.source_invoice_line_id where cl.credit_note_id=d.id order by cl.id loop
    if l.source_invoice_line_id is null or l.quantity>l.source_quantity or l.quantity+coalesce((select sum(old.quantity) from public.sales_credit_note_lines old join public.sales_credit_notes h on h.id=old.credit_note_id where old.source_invoice_line_id=l.source_invoice_line_id and h.status='posted'),0)>l.source_quantity then raise exception 'credit_exceeds_source_line'; end if;
    v_amount:=round(l.quantity*l.unit_price-l.discount,6);
    if v_amount<0 then raise exception 'invalid_credit_note_line'; end if;
    v_tax_amount:=0;
    if l.tax_rate_id is not null then select round(v_amount*t.rate_percent/100,6) into v_tax_amount from public.tax_rates t where t.id=l.tax_rate_id and t.organization_id=p_organization_id and t.sales_enabled and t.is_active; if v_tax_amount is null then raise exception 'invalid_sales_tax_rate'; end if; end if;
    v_net:=v_net+v_amount; v_tax:=v_tax+v_tax_amount;
  end loop;
  if v_net<=0 or v_net+v_tax>oi.remaining_amount then raise exception 'credit_exceeds_remaining_receivable'; end if;
  select id into v_ar from public.accounts where organization_id=p_organization_id and system_key='accounts_receivable' and is_active;
  select id into v_vat from public.accounts where organization_id=p_organization_id and system_key='output_vat' and is_active;
  select id into v_revenue from public.accounts where organization_id=p_organization_id and system_key='sales_revenue' and is_active;
  if v_ar is null or v_vat is null or v_revenue is null then raise exception 'system_account_missing'; end if;
  insert into public.journal_entries(id,organization_id,branch_id,journal_date,source_type,source_id,description,created_by) values(v_journal,p_organization_id,d.branch_id,d.credit_note_date,'sales_credit_note',d.id,'Sales credit note',auth.uid());
  for l in select * from public.sales_credit_note_lines where credit_note_id=d.id order by id loop
    v_amount:=round(l.quantity*l.unit_price-l.discount,6); v_line:=v_line+1;
    insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount,tax_rate_id,tax_amount,party_type,party_id,branch_id) values(p_organization_id,v_journal,v_line,coalesce(l.revenue_account_id,v_revenue),l.description,v_amount,0,l.tax_rate_id,0,'customer',d.customer_id,d.branch_id);
    if l.tax_rate_id is not null then v_line:=v_line+1; insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount,tax_rate_id,tax_amount,party_type,party_id,branch_id) values(p_organization_id,v_journal,v_line,v_vat,'VAT reversal: '||l.description,round(v_amount*(select rate_percent from public.tax_rates where id=l.tax_rate_id and organization_id=p_organization_id)/100,6),0,l.tax_rate_id,0,'customer',d.customer_id,d.branch_id); end if;
  end loop;
  v_line:=v_line+1; insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount,party_type,party_id,branch_id) values(p_organization_id,v_journal,v_line,v_ar,'Accounts receivable',0,v_net+v_tax,'customer',d.customer_id,d.branch_id);
  insert into public.document_sequences(organization_id,document_type,prefix) values(p_organization_id,'sales_credit_note','CN-') on conflict (organization_id,branch_id,document_type,financial_year_id) do nothing;
  select prefix,padding,suffix,next_number into v_prefix,v_padding,v_suffix,v_number from public.document_sequences where organization_id=p_organization_id and document_type='sales_credit_note' and branch_id is null and financial_year_id is null for update;
  if v_number is null then raise exception 'credit_note_sequence_missing'; end if;
  update public.document_sequences set next_number=next_number+1 where organization_id=p_organization_id and document_type='sales_credit_note' and branch_id is null and financial_year_id is null;
  update public.journal_entries set reference=v_prefix||lpad(v_number::text,v_padding,'0')||coalesce(v_suffix,'') where id=v_journal;
  perform public.post_journal_entry(p_organization_id,v_journal);
  update public.open_items set remaining_amount=remaining_amount-(v_net+v_tax),status=case when remaining_amount-(v_net+v_tax)=0 then 'settled' else 'partial' end where id=oi.id;
  insert into public.open_item_allocations(organization_id,open_item_id,sales_credit_note_id,amount) values(p_organization_id,oi.id,d.id,v_net+v_tax);
  update public.sales_credit_notes set credit_note_number=v_prefix||lpad(v_number::text,v_padding,'0')||coalesce(v_suffix,''),subtotal=v_net,tax_total=v_tax,grand_total=v_net+v_tax,status='posted',posted_journal_id=v_journal,posted_at=now(),posted_by=auth.uid() where id=d.id;
  perform public.accounting_audit(p_organization_id,'sales_credit_note.posted','sales_credit_note',d.id,jsonb_build_object('journal_id',v_journal));
  return jsonb_build_object('credit_note_id',d.id,'journal_id',v_journal,'already_posted',false);
end; $$;

