create policy sales_credit_note_lines_member_select on public.sales_credit_note_lines for select to authenticated using(public.is_active_org_member(organization_id));
revoke all on function public.replace_sales_credit_note_lines(uuid,uuid,jsonb) from public,anon,authenticated;
revoke all on function public.create_sales_credit_note_draft(uuid,uuid,uuid,date,jsonb,uuid,text,text),public.update_sales_credit_note_draft(uuid,uuid,date,jsonb,text,text),public.delete_sales_credit_note_draft(uuid,uuid),public.post_sales_credit_note(uuid,uuid) from public,anon;
grant execute on function public.create_sales_credit_note_draft(uuid,uuid,uuid,date,jsonb,uuid,text,text),public.update_sales_credit_note_draft(uuid,uuid,date,jsonb,text,text),public.delete_sales_credit_note_draft(uuid,uuid),public.post_sales_credit_note(uuid,uuid) to authenticated;

-- 4B.2 Purchase debit notes mirror the credit-note controls while reversing AP,
-- source expense/asset accounts, and input VAT.
alter table public.purchase_debit_note_lines add column source_bill_line_id uuid references public.purchase_bill_lines(id);

create or replace function public.replace_purchase_debit_note_lines(p_organization_id uuid,p_debit_note_id uuid,p_lines jsonb) returns void language plpgsql security definer set search_path=pg_catalog,public as $$
declare x jsonb; s public.purchase_bill_lines%rowtype; v_bill uuid;
begin
  perform public.assert_accounting_owner(p_organization_id);
  if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'debit_note_lines_required'; end if;
  select bill_id into v_bill from public.purchase_debit_notes where id=p_debit_note_id and organization_id=p_organization_id and status='draft' for update;
  if v_bill is null then raise exception 'debit_note_not_editable'; end if;
  delete from public.purchase_debit_note_lines where debit_note_id=p_debit_note_id;
  for x in select value from jsonb_array_elements(p_lines) loop
    select * into s from public.purchase_bill_lines where id=(x->>'source_bill_line_id')::uuid and bill_id=v_bill and organization_id=p_organization_id;
    if not found or coalesce((x->>'quantity')::numeric,0)<=0 or (x->>'quantity')::numeric>s.quantity then raise exception 'invalid_debit_note_line'; end if;
    insert into public.purchase_debit_note_lines(debit_note_id,organization_id,source_bill_line_id,description,quantity,unit_price,discount,tax_rate_id,expense_account_id)
    values(p_debit_note_id,p_organization_id,s.id,s.description,(x->>'quantity')::numeric,s.unit_price,round(s.discount*(x->>'quantity')::numeric/s.quantity,6),s.tax_rate_id,s.expense_account_id);
  end loop;
end; $$;

create or replace function public.create_purchase_debit_note_draft(p_organization_id uuid,p_supplier_id uuid,p_bill_id uuid,p_debit_note_date date,p_lines jsonb,p_branch_id uuid default null,p_reference text default null,p_notes text default null) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$
declare v_id uuid:=gen_random_uuid();
begin
  perform public.assert_accounting_owner(p_organization_id);
  if not exists(select 1 from public.purchase_bills b join public.suppliers s on s.id=b.supplier_id and s.organization_id=p_organization_id and s.is_active where b.id=p_bill_id and b.organization_id=p_organization_id and b.status='posted' and b.supplier_id=p_supplier_id and b.branch_id is not distinct from p_branch_id)
     or (p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and organization_id=p_organization_id)) then raise exception 'invalid_debit_note_source'; end if;
  insert into public.purchase_debit_notes(id,organization_id,branch_id,supplier_id,bill_id,debit_note_date,reference,notes,created_by) values(v_id,p_organization_id,p_branch_id,p_supplier_id,p_bill_id,p_debit_note_date,nullif(trim(p_reference),''),nullif(trim(p_notes),''),auth.uid());
  perform public.replace_purchase_debit_note_lines(p_organization_id,v_id,p_lines);
  perform public.accounting_audit(p_organization_id,'purchase_debit_note.created','purchase_debit_note',v_id);
  return v_id;
end; $$;

create or replace function public.update_purchase_debit_note_draft(p_organization_id uuid,p_debit_note_id uuid,p_debit_note_date date,p_lines jsonb,p_reference text default null,p_notes text default null) returns void language plpgsql security definer set search_path=pg_catalog,public as $$
begin
  perform public.assert_accounting_owner(p_organization_id);
  update public.purchase_debit_notes set debit_note_date=p_debit_note_date,reference=nullif(trim(p_reference),''),notes=nullif(trim(p_notes),'') where id=p_debit_note_id and organization_id=p_organization_id and status='draft';
  if not found then raise exception 'debit_note_not_editable'; end if;
  perform public.replace_purchase_debit_note_lines(p_organization_id,p_debit_note_id,p_lines);
  perform public.accounting_audit(p_organization_id,'purchase_debit_note.updated','purchase_debit_note',p_debit_note_id);
end; $$;
create or replace function public.delete_purchase_debit_note_draft(p_organization_id uuid,p_debit_note_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_accounting_owner(p_organization_id); delete from public.purchase_debit_notes where id=p_debit_note_id and organization_id=p_organization_id and status='draft'; if not found then raise exception 'debit_note_not_editable'; end if; end; $$;

create or replace function public.post_purchase_debit_note(p_organization_id uuid,p_debit_note_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare d public.purchase_debit_notes%rowtype; oi public.open_items%rowtype; l record; v_journal uuid:=gen_random_uuid(); v_ap uuid; v_vat uuid; v_net numeric(20,6):=0; v_tax numeric(20,6):=0; v_amount numeric(20,6); v_tax_amount numeric(20,6); v_line smallint:=0; v_number bigint; v_prefix text; v_padding smallint; v_suffix text;
begin
  perform public.assert_accounting_owner(p_organization_id);
  select * into d from public.purchase_debit_notes where id=p_debit_note_id and organization_id=p_organization_id for update;
  if not found then raise exception 'not_found'; end if;
  if d.status='posted' then return jsonb_build_object('debit_note_id',d.id,'journal_id',d.posted_journal_id,'already_posted',true); end if;
  if d.status<>'draft' or not exists(select 1 from public.purchase_bills b where b.id=d.bill_id and b.organization_id=p_organization_id and b.status='posted' and b.supplier_id=d.supplier_id and b.branch_id is not distinct from d.branch_id) then raise exception 'debit_note_not_postable'; end if;
  select * into oi from public.open_items where organization_id=p_organization_id and kind='payable' and supplier_id=d.supplier_id and source_document_id=d.bill_id for update;
  if not found then raise exception 'bill_open_item_missing'; end if;
  for l in select dl.*,bl.quantity source_quantity from public.purchase_debit_note_lines dl join public.purchase_bill_lines bl on bl.id=dl.source_bill_line_id where dl.debit_note_id=d.id order by dl.id loop
    if l.source_bill_line_id is null or l.quantity>l.source_quantity or l.quantity+coalesce((select sum(old.quantity) from public.purchase_debit_note_lines old join public.purchase_debit_notes h on h.id=old.debit_note_id where old.source_bill_line_id=l.source_bill_line_id and h.status='posted'),0)>l.source_quantity then raise exception 'debit_exceeds_source_line'; end if;
    v_amount:=round(l.quantity*l.unit_price-l.discount,6); if v_amount<0 then raise exception 'invalid_debit_note_line'; end if;
    v_tax_amount:=0; if l.tax_rate_id is not null then select round(v_amount*t.rate_percent/100,6) into v_tax_amount from public.tax_rates t where t.id=l.tax_rate_id and t.organization_id=p_organization_id and t.purchase_enabled and t.is_active; if v_tax_amount is null then raise exception 'invalid_purchase_tax_rate'; end if; end if;
    v_net:=v_net+v_amount; v_tax:=v_tax+v_tax_amount;
  end loop;
  if v_net<=0 or v_net+v_tax>oi.remaining_amount then raise exception 'debit_exceeds_remaining_payable'; end if;
  select id into v_ap from public.accounts where organization_id=p_organization_id and system_key='accounts_payable' and is_active;
  select id into v_vat from public.accounts where organization_id=p_organization_id and system_key='input_vat' and is_active;
  if v_ap is null or v_vat is null then raise exception 'system_account_missing'; end if;
  insert into public.journal_entries(id,organization_id,branch_id,journal_date,source_type,source_id,description,created_by) values(v_journal,p_organization_id,d.branch_id,d.debit_note_date,'purchase_debit_note',d.id,'Purchase debit note',auth.uid());
  for l in select * from public.purchase_debit_note_lines where debit_note_id=d.id order by id loop
    v_amount:=round(l.quantity*l.unit_price-l.discount,6); v_line:=v_line+1;
    insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount,tax_rate_id,tax_amount,party_type,party_id,branch_id) values(p_organization_id,v_journal,v_line,l.expense_account_id,l.description,0,v_amount,l.tax_rate_id,0,'supplier',d.supplier_id,d.branch_id);
    if l.tax_rate_id is not null then v_line:=v_line+1; insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount,tax_rate_id,tax_amount,party_type,party_id,branch_id) values(p_organization_id,v_journal,v_line,v_vat,'VAT reversal: '||l.description,0,round(v_amount*(select rate_percent from public.tax_rates where id=l.tax_rate_id and organization_id=p_organization_id)/100,6),l.tax_rate_id,0,'supplier',d.supplier_id,d.branch_id); end if;
  end loop;
  v_line:=v_line+1; insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount,party_type,party_id,branch_id) values(p_organization_id,v_journal,v_line,v_ap,'Accounts payable',v_net+v_tax,0,'supplier',d.supplier_id,d.branch_id);
  insert into public.document_sequences(organization_id,document_type,prefix) values(p_organization_id,'purchase_debit_note','DN-') on conflict (organization_id,branch_id,document_type,financial_year_id) do nothing;
  select prefix,padding,suffix,next_number into v_prefix,v_padding,v_suffix,v_number from public.document_sequences where organization_id=p_organization_id and document_type='purchase_debit_note' and branch_id is null and financial_year_id is null for update;
  if v_number is null then raise exception 'debit_note_sequence_missing'; end if;
  update public.document_sequences set next_number=next_number+1 where organization_id=p_organization_id and document_type='purchase_debit_note' and branch_id is null and financial_year_id is null;
  update public.journal_entries set reference=v_prefix||lpad(v_number::text,v_padding,'0')||coalesce(v_suffix,'') where id=v_journal;
  perform public.post_journal_entry(p_organization_id,v_journal);
  update public.open_items set remaining_amount=remaining_amount-(v_net+v_tax),status=case when remaining_amount-(v_net+v_tax)=0 then 'settled' else 'partial' end where id=oi.id;
  insert into public.open_item_allocations(organization_id,open_item_id,purchase_debit_note_id,amount) values(p_organization_id,oi.id,d.id,v_net+v_tax);
  update public.purchase_debit_notes set debit_note_number=v_prefix||lpad(v_number::text,v_padding,'0')||coalesce(v_suffix,''),subtotal=v_net,tax_total=v_tax,grand_total=v_net+v_tax,status='posted',posted_journal_id=v_journal,posted_at=now(),posted_by=auth.uid() where id=d.id;
  perform public.accounting_audit(p_organization_id,'purchase_debit_note.posted','purchase_debit_note',d.id,jsonb_build_object('journal_id',v_journal));
  return jsonb_build_object('debit_note_id',d.id,'journal_id',v_journal,'already_posted',false);
end; $$;

create trigger purchase_debit_notes_phase4b_updated before update on public.purchase_debit_notes for each row execute function public.set_updated_at();
create policy purchase_debit_note_lines_member_select on public.purchase_debit_note_lines for select to authenticated using(public.is_active_org_member(organization_id));
revoke all on function public.replace_purchase_debit_note_lines(uuid,uuid,jsonb) from public,anon,authenticated;
revoke all on function public.create_purchase_debit_note_draft(uuid,uuid,uuid,date,jsonb,uuid,text,text),public.update_purchase_debit_note_draft(uuid,uuid,date,jsonb,text,text),public.delete_purchase_debit_note_draft(uuid,uuid),public.post_purchase_debit_note(uuid,uuid) from public,anon;
grant execute on function public.create_purchase_debit_note_draft(uuid,uuid,uuid,date,jsonb,uuid,text,text),public.update_purchase_debit_note_draft(uuid,uuid,date,jsonb,text,text),public.delete_purchase_debit_note_draft(uuid,uuid),public.post_purchase_debit_note(uuid,uuid) to authenticated;

-- 4B.3 Supplier payments: allocations are required to equal the payment amount,
-- leaving open_items.remaining_amount as the only AP settlement balance.
create or replace function public.assert_settlement_cash_account(p_organization_id uuid,p_account_id uuid,p_branch_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_accounting_owner(p_organization_id); if not exists(select 1 from public.accounts a where a.id=p_account_id and a.organization_id=p_organization_id and a.is_active and ((a.account_type='cash' and exists(select 1 from public.cash_accounts c where c.organization_id=p_organization_id and c.account_id=a.id and c.is_active and (p_branch_id is null or c.branch_id is null or c.branch_id=p_branch_id))) or (a.account_type='bank' and exists(select 1 from public.bank_accounts b where b.organization_id=p_organization_id and b.account_id=a.id and b.is_active and (p_branch_id is null or b.branch_id is null or b.branch_id=p_branch_id))))) then raise exception 'invalid_cash_or_bank_account'; end if; end; $$;
create or replace function public.create_supplier_payment_draft(p_organization_id uuid,p_supplier_id uuid,p_payment_date date,p_cash_account_id uuid,p_amount numeric,p_branch_id uuid default null,p_reference text default null,p_notes text default null) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare v uuid:=gen_random_uuid(); begin perform public.assert_settlement_cash_account(p_organization_id,p_cash_account_id,p_branch_id); if p_amount<=0 or (p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and organization_id=p_organization_id)) or not exists(select 1 from public.suppliers where id=p_supplier_id and organization_id=p_organization_id and is_active) then raise exception 'invalid_supplier_payment'; end if; insert into public.supplier_payments(id,organization_id,branch_id,supplier_id,payment_date,cash_account_id,amount,reference,notes,created_by) values(v,p_organization_id,p_branch_id,p_supplier_id,p_payment_date,p_cash_account_id,p_amount,nullif(trim(p_reference),''),nullif(trim(p_notes),''),auth.uid()); perform public.accounting_audit(p_organization_id,'supplier_payment.created','supplier_payment',v); return v; end; $$;
create or replace function public.update_supplier_payment_draft(p_organization_id uuid,p_payment_id uuid,p_supplier_id uuid,p_payment_date date,p_cash_account_id uuid,p_amount numeric,p_branch_id uuid default null,p_reference text default null,p_notes text default null) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_settlement_cash_account(p_organization_id,p_cash_account_id,p_branch_id); if p_amount<=0 or (p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and organization_id=p_organization_id)) or not exists(select 1 from public.suppliers where id=p_supplier_id and organization_id=p_organization_id and is_active) then raise exception 'invalid_supplier_payment'; end if; update public.supplier_payments set supplier_id=p_supplier_id,payment_date=p_payment_date,cash_account_id=p_cash_account_id,amount=p_amount,branch_id=p_branch_id,reference=nullif(trim(p_reference),''),notes=nullif(trim(p_notes),'') where id=p_payment_id and organization_id=p_organization_id and status='draft'; if not found then raise exception 'payment_not_editable'; end if; perform public.accounting_audit(p_organization_id,'supplier_payment.updated','supplier_payment',p_payment_id); end; $$;
create or replace function public.delete_supplier_payment_draft(p_organization_id uuid,p_payment_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_accounting_owner(p_organization_id); delete from public.supplier_payments where id=p_payment_id and organization_id=p_organization_id and status='draft'; if not found then raise exception 'payment_not_editable'; end if; end; $$;
create or replace function public.post_supplier_payment(p_organization_id uuid,p_payment_id uuid,p_allocations jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$ declare d public.supplier_payments%rowtype; x jsonb; oi public.open_items%rowtype; v_total numeric(20,6):=0; v_amount numeric(20,6); v_ap uuid; v_journal uuid:=gen_random_uuid(); v_n bigint; v_prefix text; v_padding smallint; v_suffix text; begin perform public.assert_accounting_owner(p_organization_id); select * into d from public.supplier_payments where id=p_payment_id and organization_id=p_organization_id for update; if not found then raise exception 'not_found'; end if; if d.status='posted' then return jsonb_build_object('payment_id',d.id,'journal_id',d.posted_journal_id,'already_posted',true); end if; perform public.assert_settlement_cash_account(p_organization_id,d.cash_account_id,d.branch_id); if jsonb_typeof(p_allocations)<>'array' then raise exception 'invalid_allocations'; end if; for x in select value from jsonb_array_elements(p_allocations) loop v_amount:=(x->>'amount')::numeric; select oi.* into oi from public.open_items oi join public.purchase_bills b on b.id=oi.source_document_id and b.organization_id=p_organization_id and b.status='posted' where oi.id=(x->>'open_item_id')::uuid and oi.organization_id=p_organization_id for update; if not found or oi.kind<>'payable' or oi.supplier_id<>d.supplier_id or v_amount<=0 or v_amount>oi.remaining_amount then raise exception 'invalid_supplier_payment_allocation'; end if; v_total:=v_total+v_amount; end loop; if v_total<>d.amount then raise exception 'payment_allocation_must_equal_amount'; end if; select id into v_ap from public.accounts where organization_id=p_organization_id and system_key='accounts_payable' and is_active; if v_ap is null then raise exception 'system_account_missing'; end if; insert into public.journal_entries(id,organization_id,branch_id,journal_date,source_type,source_id,description,created_by) values(v_journal,p_organization_id,d.branch_id,d.payment_date,'supplier_payment',d.id,'Supplier payment',auth.uid()); insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount,party_type,party_id,branch_id) values(p_organization_id,v_journal,1,v_ap,'Accounts payable',d.amount,0,'supplier',d.supplier_id,d.branch_id),(p_organization_id,v_journal,2,d.cash_account_id,'Supplier payment',0,d.amount,'supplier',d.supplier_id,d.branch_id); insert into public.document_sequences(organization_id,document_type,prefix) values(p_organization_id,'payment','PAY-') on conflict (organization_id,branch_id,document_type,financial_year_id) do nothing; select prefix,padding,suffix,next_number into v_prefix,v_padding,v_suffix,v_n from public.document_sequences where organization_id=p_organization_id and document_type='payment' and branch_id is null and financial_year_id is null for update; if v_n is null then raise exception 'payment_sequence_missing'; end if; update public.document_sequences set next_number=v_n+1 where organization_id=p_organization_id and document_type='payment' and branch_id is null and financial_year_id is null; update public.journal_entries set reference=v_prefix||lpad(v_n::text,v_padding,'0')||coalesce(v_suffix,'') where id=v_journal; perform public.post_journal_entry(p_organization_id,v_journal); for x in select value from jsonb_array_elements(p_allocations) loop v_amount:=(x->>'amount')::numeric; update public.open_items set remaining_amount=remaining_amount-v_amount,status=case when remaining_amount-v_amount=0 then 'settled' else 'partial' end where id=(x->>'open_item_id')::uuid; insert into public.open_item_allocations(organization_id,open_item_id,supplier_payment_id,amount) values(p_organization_id,(x->>'open_item_id')::uuid,d.id,v_amount); end loop; update public.supplier_payments set payment_number=v_prefix||lpad(v_n::text,v_padding,'0')||coalesce(v_suffix,''),status='posted',posted_journal_id=v_journal,posted_at=now(),posted_by=auth.uid() where id=d.id; perform public.accounting_audit(p_organization_id,'supplier_payment.posted','supplier_payment',d.id,jsonb_build_object('journal_id',v_journal)); return jsonb_build_object('payment_id',d.id,'journal_id',v_journal,'already_posted',false); end; $$;
create trigger supplier_payments_phase4b_updated before update on public.supplier_payments for each row execute function public.set_updated_at();
revoke all on function public.assert_settlement_cash_account(uuid,uuid,uuid) from public,anon,authenticated;
revoke all on function public.create_supplier_payment_draft(uuid,uuid,date,uuid,numeric,uuid,text,text),public.update_supplier_payment_draft(uuid,uuid,uuid,date,uuid,numeric,uuid,text,text),public.delete_supplier_payment_draft(uuid,uuid),public.post_supplier_payment(uuid,uuid,jsonb) from public,anon;
grant execute on function public.create_supplier_payment_draft(uuid,uuid,date,uuid,numeric,uuid,text,text),public.update_supplier_payment_draft(uuid,uuid,uuid,date,uuid,numeric,uuid,text,text),public.delete_supplier_payment_draft(uuid,uuid),public.post_supplier_payment(uuid,uuid,jsonb) to authenticated;

-- Allocation payloads must not repeat an open item.  Keep the original posters
-- private and place this validation before either can create a journal or mutate
-- an open item.  The original transaction still locks each validated target.
alter function public.post_customer_receipt(uuid,uuid,jsonb) rename to post_customer_receipt_internal;
alter function public.post_supplier_payment(uuid,uuid,jsonb) rename to post_supplier_payment_internal;
revoke all on function public.post_customer_receipt_internal(uuid,uuid,jsonb),public.post_supplier_payment_internal(uuid,uuid,jsonb) from public,anon,authenticated;
create or replace function public.assert_unique_settlement_allocation_targets(p_organization_id uuid,p_allocations jsonb) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ declare v_count integer; v_distinct integer; begin perform public.assert_accounting_owner(p_organization_id); if jsonb_typeof(p_allocations)<>'array' then raise exception 'invalid_allocations'; end if; select count(*),count(distinct value->>'open_item_id') into v_count,v_distinct from jsonb_array_elements(p_allocations); if v_count<>v_distinct or exists(select 1 from jsonb_array_elements(p_allocations) where nullif(value->>'open_item_id','') is null) then raise exception 'duplicate_or_missing_allocation_target'; end if; end; $$;
create or replace function public.post_customer_receipt(p_organization_id uuid,p_receipt_id uuid,p_allocations jsonb default '[]'::jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_unique_settlement_allocation_targets(p_organization_id,p_allocations); return public.post_customer_receipt_internal(p_organization_id,p_receipt_id,p_allocations); end; $$;
create or replace function public.post_supplier_payment(p_organization_id uuid,p_payment_id uuid,p_allocations jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_unique_settlement_allocation_targets(p_organization_id,p_allocations); return public.post_supplier_payment_internal(p_organization_id,p_payment_id,p_allocations); end; $$;
